SourceCode.Declaration:
/// <summary>
/// The request of the inbound sales order API.
/// </summary>
[DataContractAttribute]
public class DYLO_SalesOrderApiRequestContract
{
    DYLO_CorrelationId      correlationId;
    DYLO_ExternalOrderRef   externalOrderId;
    DataAreaId              legalEntity;
    CustAccount             customerAccount;
    CurrencyCode            currency;
    TransDate               requestedShipDate;
    CustPurchaseOrder       customerPoReference;
    List                    lines;
}

Method.Source:
[DataMemberAttribute('correlationId')]
public DYLO_CorrelationId parmCorrelationId(DYLO_CorrelationId _correlationId = correlationId)
{
    correlationId = _correlationId;
    return correlationId;
}

[DataMemberAttribute('externalOrderId')]
public DYLO_ExternalOrderRef parmExternalOrderId(DYLO_ExternalOrderRef _externalOrderId = externalOrderId)
{
    externalOrderId = _externalOrderId;
    return externalOrderId;
}

[DataMemberAttribute('legalEntity')]
public DataAreaId parmLegalEntity(DataAreaId _legalEntity = legalEntity)
{
    legalEntity = _legalEntity;
    return legalEntity;
}

[DataMemberAttribute('customerAccount')]
public CustAccount parmCustomerAccount(CustAccount _customerAccount = customerAccount)
{
    customerAccount = _customerAccount;
    return customerAccount;
}

[DataMemberAttribute('currency')]
public CurrencyCode parmCurrency(CurrencyCode _currency = currency)
{
    currency = _currency;
    return currency;
}

[DataMemberAttribute('requestedShipDate')]
public TransDate parmRequestedShipDate(TransDate _requestedShipDate = requestedShipDate)
{
    requestedShipDate = _requestedShipDate;
    return requestedShipDate;
}

[DataMemberAttribute('customerPoReference')]
public CustPurchaseOrder parmCustomerPoReference(CustPurchaseOrder _customerPoReference = customerPoReference)
{
    customerPoReference = _customerPoReference;
    return customerPoReference;
}

/// <summary>
/// The order lines, a list of <c>DYLO_SalesOrderApiLineContract</c>.
/// </summary>
[
    DataMemberAttribute('lines'),
    AifCollectionTypeAttribute('_lines', Types::Class, classStr(DYLO_SalesOrderApiLineContract)),
    AifCollectionTypeAttribute('return', Types::Class, classStr(DYLO_SalesOrderApiLineContract)),
    DataCollectionAttribute(Types::Class, classStr(DYLO_SalesOrderApiLineContract))
]
public List parmLines(List _lines = lines)
{
    lines = _lines;
    return lines;
}

/// <summary>
/// Gets the number of order lines.
/// </summary>
public int lineCount()
{
    return lines ? lines.elements() : 0;
}
